def parse_metadata_block(body: str) -> dict:
    """Read the identity block back. Returns {} when absent or incomplete.

    Uses the same bounds as :func:`upsert_metadata_block` so the reader and the
    writer agree on which block is authoritative. A body may quote a stray or
    unfinished block — an example in prose, an interrupted earlier write — and
    naively pairing the first BEGIN with the first END would then span from
    that stray marker into the real block, or past a trailing unfinished one,
    and pick up fields that belong to neither.
    """
    if not body or METADATA_BEGIN not in body:
        return {}
    bounds = _metadata_bounds(body)
    if bounds is None:
        return {}
    start, end = bounds
    inner = body[start + len(METADATA_BEGIN) : end - len(METADATA_END)]
    fields: dict = {}

