def _unmanaged_regions(text: str) -> Tuple[str, str]:
    """Split what this provider does not own: loose prose, then foreign sections.

    Both are returned so a rewrite can put them back. Prose written above the
    first `##` heading used to be dropped on the floor, because only headed
    sections were collected.

    The managed metadata block's own span is found the same way the writer
    finds it (`metadata_bounds`), not by toggling on every stray marker line.
    A quoted or unfinished example elsewhere in the file is then ordinary text
    to this function — it is preserved, not swallowed as if it were the block.
    """
    if not text:
        return "", ""
    bounds = metadata_bounds(text)
    if bounds is not None:
        start, end = bounds
        text = text[:start] + text[end:]
    preamble: List[str] = []
    kept: List[str] = []
    keeping = None
    for line in text.splitlines():
        match = SECTION_RE.match(line)
        if match:
            keeping = match.group("name").strip().lower() not in MANAGED_SECTIONS
        if keeping is None:
            if not _is_generated_head_line(line):
                preamble.append(line)
        elif keeping:
            kept.append(line)
    return "\n".join(preamble).strip(), "\n".join(kept)
